const strategies = {
  normal: (r) => r,
  doubleSix: (r) => (r === 6 ? 12 : r),
  capped: (r) => Math.min(r, 4),
};
function play(rolls, name) {
  const s = strategies[name] ?? strategies.normal;
  return rolls.reduce((pos, r) => pos + s(r), 0);
}
console.log(play([6, 2, 5], 'doubleSix'), play([6, 2, 5], 'capped'), play([6, 2, 5], 'turbo'));

class Idle { move(g) { g.state = new Playing(); return 'start'; } }
class Playing {
  constructor() { this.moves = 0; }
  move(g) {
    this.moves++;
    if (this.moves === 2) g.state = new Over();
    return 'move' + this.moves;
  }
}
class Over { move() { return 'ignored'; } }
const g = { state: new Idle() };
const out = [];
for (let i = 0; i < 5; i++) out.push(g.state.move(g));
console.log(out.join(','));

